body:
A starter API plugin for an IT service desk. It exposes three functions to a declarative agent in Microsoft 365 Copilot: list my tickets, get one ticket, and create a ticket. The plugin manifest uses schema v2.4 (Microsoft Learn: API and MCP plugin manifest schema 2.4). Every function declares security_info.data_handling so it can be combined with other plugins and capabilities of the agent, createTicket asks for confirmation, and listMyTickets overrides the responding state with short formatting rules. All hosts, URLs and IDs are placeholders from the contoso.example namespace; replace them with your own.

=== File: ai-plugin.json (plugin manifest) ===
Comment: function names must equal the operationId values in the OpenAPI file. name_for_human may be cut after 20 characters, description_for_human after 100 and description_for_model after 2048. The reference_id is the auth config ID you receive when you register the OAuth settings; secrets never go into the manifest.
{
 "$schema": "https://developer.microsoft.com/json-schemas/copilot/plugin/v2.4/schema.json",
 "schema_version": "v2.4",
 "name_for_human": "IT Service Desk",
 "namespace": "ContosoItsm",
 "description_for_human": "Find, view and open IT support tickets from Microsoft 365 Copilot.",
 "description_for_model": "Use this plugin when the user asks about IT support tickets: listing their own tickets, looking up one ticket by number, or opening a new ticket for a hardware, software or access problem. Ticket numbers look like INC followed by digits. Do not use it for HR, facilities or purchasing requests. Never invent ticket numbers; always take them from a function result.",
 "contact_email": "itsm-support@contoso.example",
 "privacy_policy_url": "https://contoso.example/privacy",
 "legal_info_url": "https://contoso.example/legal",
 "functions": [
  {
   "name": "listMyTickets",
   "description": "Lists the signed-in user's IT tickets, newest first, optionally filtered by status.",
   "parameters": {
    "type": "object",
    "properties": {
     "status": {
      "type": "string",
      "description": "Ticket status filter.",
      "enum": [
       "open",
       "resolved",
       "all"
      ]
     }
    }
   },
   "capabilities": {
    "security_info": {
     "data_handling": [
      "GetPrivateData"
     ]
    }
   },
   "states": {
    "responding": {
     "description": "Summarizes the ticket list.",
     "instructions": [
      "Show at most 5 tickets, newest first, with number, title and status.",
      "If the result contains an error field, explain it briefly and do not guess ticket data."
     ]
    }
   }
  },
  {
   "name": "getTicket",
   "description": "Returns the full details and latest comment of one ticket by its number.",
   "parameters": {
    "type": "object",
    "properties": {
     "ticketNumber": {
      "type": "string",
      "description": "Ticket number such as INC0012345."
     }
    },
    "required": [
     "ticketNumber"
    ]
   },
   "capabilities": {
    "security_info": {
     "data_handling": [
      "GetPrivateData"
     ]
    }
   }
  },
  {
   "name": "createTicket",
   "description": "Opens a new IT support ticket for the signed-in user.",
   "parameters": {
    "type": "object",
    "properties": {
     "title": {
      "type": "string",
      "description": "One-line summary of the problem."
     },
     "description": {
      "type": "string",
      "description": "What happened, what was expected and any error text."
     },
     "category": {
      "type": "string",
      "description": "Ticket category.",
      "enum": [
       "hardware",
       "software",
       "access",
       "network"
      ]
     }
    },
    "required": [
     "title",
     "description"
    ]
   },
   "capabilities": {
    "confirmation": {
     "type": "AdaptiveCard",
     "title": "Open an IT ticket",
     "body": "Copilot will open a ticket with the title and description you provided. Continue?"
    },
    "security_info": {
     "data_handling": [
      "ResourceStateUpdate"
     ]
    }
   }
  }
 ],
 "runtimes": [
  {
   "type": "OpenApi",
   "auth": {
    "type": "OAuthPluginVault",
    "reference_id": "REPLACE_WITH_AUTH_CONFIG_ID"
   },
   "spec": {
    "url": "openapi.json",
    "progress_style": "ShowUsage"
   }
  }
 ]
}

=== File: openapi.json (OpenAPI 3.0.1 description, shortened) ===
Comment: the server URL must be HTTPS, each operation needs an operationId, and descriptions should tell the model when to use the call. The OAuth URLs below are placeholders; the real client ID, secret and scopes are stored in the auth config.
{
 "openapi": "3.0.1",
 "info": {
  "title": "IT Service Desk API",
  "description": "Read and create IT support tickets for the signed-in user.",
  "version": "1.0.0"
 },
 "servers": [
  {
   "url": "https://itsm.contoso.example/api"
  }
 ],
 "paths": {
  "/tickets": {
   "get": {
    "operationId": "listMyTickets",
    "summary": "List my tickets",
    "description": "Returns the caller's tickets, newest first.",
    "parameters": [
     {
      "name": "status",
      "in": "query",
      "required": false,
      "description": "open, resolved or all.",
      "schema": {
       "type": "string",
       "enum": [
        "open",
        "resolved",
        "all"
       ]
      }
     }
    ],
    "responses": {
     "200": {
      "description": "Ticket list",
      "content": {
       "application/json": {
        "schema": {
         "type": "array",
         "items": {
          "$ref": "#/components/schemas/Ticket"
         }
        }
       }
      }
     },
     "401": {
      "description": "Not authenticated"
     }
    }
   },
   "post": {
    "operationId": "createTicket",
    "summary": "Create a ticket",
    "description": "Opens a new ticket for the caller.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "type": "object",
        "required": [
         "title",
         "description"
        ],
        "properties": {
         "title": {
          "type": "string"
         },
         "description": {
          "type": "string"
         },
         "category": {
          "type": "string",
          "enum": [
           "hardware",
           "software",
           "access",
           "network"
          ]
         }
        }
       }
      }
     }
    },
    "responses": {
     "201": {
      "description": "Created ticket",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Ticket"
        }
       }
      }
     }
    }
   }
  },
  "/tickets/{ticketNumber}": {
   "get": {
    "operationId": "getTicket",
    "summary": "Get one ticket",
    "description": "Returns one ticket by number.",
    "parameters": [
     {
      "name": "ticketNumber",
      "in": "path",
      "required": true,
      "description": "For example INC0012345.",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "Ticket",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Ticket"
        }
       }
      }
     },
     "404": {
      "description": "No such ticket"
     }
    }
   }
  }
 },
 "components": {
  "schemas": {
   "Ticket": {
    "type": "object",
    "properties": {
     "number": {
      "type": "string"
     },
     "title": {
      "type": "string"
     },
     "status": {
      "type": "string"
     },
     "category": {
      "type": "string"
     },
     "lastComment": {
      "type": "string"
     }
    }
   }
  },
  "securitySchemes": {
   "OAuth2": {
    "type": "oauth2",
    "flows": {
     "authorizationCode": {
      "authorizationUrl": "https://login.contoso.example/oauth2/authorize",
      "tokenUrl": "https://login.contoso.example/oauth2/token",
      "scopes": {
       "tickets.read": "Read your tickets",
       "tickets.write": "Create tickets for you"
      }
     }
    }
   }
  }
 }
}

=== How to use ===
1. Save the two files in your app package folder, reference ai-plugin.json from the declarative agent through an actions entry such as {"id": "itTickets", "file": "ai-plugin.json"}, and package everything as a Microsoft 365 app.
2. Register the OAuth 2.0 settings (client ID, secret, authorization and token URLs, scopes, plus offline_access if you use the Microsoft identity platform) in the Teams developer portal or with the Microsoft 365 Agents Toolkit, and paste the generated auth config ID into reference_id.
3. Replace the server URL, contact_email, privacy and legal URLs with real values and make sure the API returns small, well-described JSON.
4. Sideload the package, ask the agent for 'my open tickets' and check which function Copilot calls; adjust descriptions until the right function is chosen every time.
5. Use the confirmation prompt of createTicket as the control point for state changes and keep read functions free of side effects.

=== Common mistakes ===
- Function name and operationId differ by even one letter, so the function is not bound to the operation.
- Using GetPrivateData for a function that writes data. Writes should declare ResourceStateUpdate, and omitting security_info stops the function from interacting with other plugins.
- Putting a client secret or token into the manifest or the OpenAPI file instead of using OAuthPluginVault with a reference_id.
- Writing a vague description_for_model such as 'ticket tool'; the orchestrator needs explicit when-to-use and when-not-to-use rules.
- Adding properties that the schema does not define; unrecognized properties can make the whole document invalid.

A read-only CRM lookup plugin in the style of a Dynamics 365 or Salesforce integration. It shows how response_semantics turns an API result into Adaptive Card output: data_path selects the array, properties maps title, subtitle and url, and static_template renders each opportunity with Adaptive Card template language (Microsoft Learn: Adaptive Card response templates for API plugins). Plugin manifest schema v2.4 is used.

=== File: ai-plugin.json ===
Comment: data_path is a JSONPath query. The card is bound to each selected item, so fields such as name and stage are referenced directly. The card uses version 1.5 as in the Microsoft examples.
{
 "$schema": "https://developer.microsoft.com/json-schemas/copilot/plugin/v2.4/schema.json",
 "schema_version": "v2.4",
 "name_for_human": "CRM Lookup",
 "namespace": "ContosoCrm",
 "description_for_human": "Look up customer accounts and open sales opportunities in the CRM.",
 "description_for_model": "Use this plugin when the user asks about a customer account, its owner, or its open sales opportunities. Call findAccounts first when you only have a company name, then use the returned accountId for listOpenOpportunities. The plugin is read-only: it cannot create or change CRM records. Amounts are in the account's currency.",
 "contact_email": "sales-ops@contoso.example",
 "functions": [
  {
   "name": "findAccounts",
   "description": "Searches CRM accounts by name and returns up to 5 matches with account ID, owner and industry.",
   "parameters": {
    "type": "object",
    "properties": {
     "name": {
      "type": "string",
      "description": "Full or partial company name."
     }
    },
    "required": [
     "name"
    ]
   },
   "capabilities": {
    "security_info": {
     "data_handling": [
      "GetPrivateData"
     ]
    }
   }
  },
  {
   "name": "listOpenOpportunities",
   "description": "Lists the open opportunities of one account, largest first.",
   "parameters": {
    "type": "object",
    "properties": {
     "accountId": {
      "type": "string",
      "description": "Account ID returned by findAccounts."
     },
     "minAmount": {
      "type": "number",
      "description": "Only return opportunities worth at least this amount."
     }
    },
    "required": [
     "accountId"
    ]
   },
   "capabilities": {
    "response_semantics": {
     "data_path": "$.opportunities",
     "properties": {
      "title": "$.name",
      "subtitle": "$.stage",
      "url": "$.webUrl"
     },
     "static_template": {
      "type": "AdaptiveCard",
      "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
      "version": "1.5",
      "body": [
       {
        "type": "TextBlock",
        "text": "${name}",
        "weight": "Bolder",
        "size": "Medium",
        "wrap": true
       },
       {
        "type": "FactSet",
        "facts": [
         {
          "title": "Account",
          "value": "${if(accountName, accountName, 'N/A')}"
         },
         {
          "title": "Stage",
          "value": "${if(stage, stage, 'N/A')}"
         },
         {
          "title": "Amount",
          "value": "${if(amount, formatNumber(amount, 2), 'N/A')}"
         },
         {
          "title": "Close date",
          "value": "${if(closeDate, closeDate, 'N/A')}"
         }
        ]
       }
      ],
      "actions": [
       {
        "type": "Action.OpenUrl",
        "title": "Open in CRM",
        "url": "${webUrl}"
       }
      ]
     }
    },
    "security_info": {
     "data_handling": [
      "GetPrivateData"
     ]
    }
   }
  }
 ],
 "runtimes": [
  {
   "type": "OpenApi",
   "auth": {
    "type": "OAuthPluginVault",
    "reference_id": "REPLACE_WITH_AUTH_CONFIG_ID"
   },
   "spec": {
    "url": "crm-openapi.json"
   }
  }
 ]
}

